from pathlib import Path
import hashlib,json
R=Path(__file__).resolve().parents[1];W=Path('./.local/station-realism');C=W/'central-gate-passage-02';O=R/'notes/central-gate-passage-bridge';O.mkdir(exist_ok=True)
files={n:C/n for n in ['report.json','serialization.json','normals.json']}
files.update({'spec.json':W/'central-gate-passage-spec-02/spec.json','observation.json':W/'central-gate-passage-spec-02/observation.json','native-walks.json':W/'central-gate-passage-walk-04/report.json','first-draft-report.json':W/'central-gate-passage-01/report.json','first-draft-walks.json':W/'central-gate-passage-walk-03/report.json','first-reference.png':W/'central-gate-passage-01/reference/source.png','first-reference-receipt.json':W/'central-gate-passage-01/reference/projection.json'})
for view in ['front','under','inside','reference']:files[view+'.png']=C/view/'source.png';files[view+'-receipt.json']=C/view/'projection.json'
manifest=[]
for n,p in files.items():
 b=p.read_bytes();(O/n).write_bytes(b);manifest.append({'file':n,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)})
(O/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
walk=json.loads(files['native-walks.json'].read_text());assert walk['pass'] and len(walk['walks'])==8 and len(walk['checks'])==36
assert walk['nativeSha256']==json.loads(files['report.json'].read_text())['outputs']['nativePanelsSha256']
figs=''.join(f'<figure><img src="{v}.png" alt="{caption}"><figcaption>{caption}</figcaption></figure>'for v,caption in [('front','Revised passage and bridge: studio construction view'),('under','Curved bridge underside; paid-concourse continuation remains unfinished'),('inside','Glazed crossing with real floor and end openings; surrounding hotel wings remain unfinished')])
links=''.join(f'<li><a href="{n}">{n}</a></li>'for n in files if n.endswith('.json'))
(O/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gate passage and bridge construction</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f2eb;color:#24362e;font:16px/1.55 system-ui}main{max-width:1248px;margin:auto;padding:24px}h1{line-height:1.15}a{color:#176749;overflow-wrap:anywhere}figure{margin:24px 0}img{width:100%;display:block}figcaption{background:#e2e7de;padding:12px}.status{padding:18px;background:#f1dfb6}.pair{position:relative;aspect-ratio:1.5;overflow:hidden}.pair img{position:absolute;inset:0;width:100%;height:auto}.pair #model{opacity:.5}label{display:block;margin:16px 0}li{margin:7px 0}</style><main><a href="../../index.html">Research library</a><h1>Gate passage and glazed bridge</h1><p class="status">Provisional, uninstalled construction. The bridge is now visible from the unchanged reference camera, but one wall-contact observation does not establish its dimensions. Full station integration and photographic acceptance remain open.</p><p>191 records · 42 colliding solids · 2,480 triangles · seven material batches · zero textures. Shared geometry and normals pass. Isolated native checks pass:36 floor/headroom probes and eight walks.</p>'''+figs+'''<h2>Fixed camera: reference and two drafts</h2><p>The first deep bridge was hidden behind a return. A provisional east-wall contact raises and moves it forward. No camera was moved for this comparison. The photo includes the whole station; these renders include only the component study. Unmodeled context is visible as sky.</p><label>Draft <select id="draft"><option value="reference.png">Revised bridge</option><option value="first-reference.png">Rejected deep bridge</option></select></label><label>Model opacity <input id="opacity" type="range" min="0" max="1" step=".01" value=".5"></label><div class="pair"><img src="../../photos/hall-maeda-2026.jpg" alt="July2026 central hall reference by MaedaAkihiko"><img id="model" src="reference.png" alt="Unchanged-camera construction render"></div><p>Reference: <a href="https://commons.wikimedia.org/wiki/File:JRW_Kyoto-STA_Central-Inside.jpg">MaedaAkihiko,26July2026</a>. The existing upper-architecture camera fit is insufficient to accept lower depth. A±24px sensitivity study spans floorY8.46–10.72m and setback5.52–7.87m; these are not statistical confidence limits.</p><h2>Corridor detail references</h2><figure><img src="../../photos/granvia-bridge-entry.jpg" alt="Straight hotel corridor with glazing, rails and ceiling ribs"><figcaption>Hotel corridor entry. Research-only photograph from the linked travel account; capture year unresolved.</figcaption></figure><figure><img src="../../photos/granvia-bridge-inside.jpg" alt="Corridor glazing looking toward the railway"><figcaption>Railway side of the corridor. Full-height glazing, dark floor and small lamps.</figcaption></figure><p><a href="https://chottoiitoko.com/kashikojimabasaratei-shimakaze/">Photographer's article</a> · <a href="https://iko-yo.net/experiences/88517">March2024 corridor-location account</a> · <a href="https://jrwest-hotels.jp/granvia-kyoto/floor/">Official M3F map</a>.</p><p>The passage still needs its widening into the paid concourse, reliable bridge/end-level evidence and gate equipment. Current active game assets and complete basement candidate remain unchanged. <a href="../CENTRAL-GATE-PASSAGE-BRIDGE.md">Full findings and next work</a>.</p><h2>Evidence</h2><ul>'''+links+'''<li><a href="manifest.json">Published hashes</a></li></ul></main><script>const m=document.querySelector('#model');document.querySelector('#draft').onchange=e=>m.src=e.target.value;document.querySelector('#opacity').oninput=e=>m.style.opacity=e.target.value;</script></html>''')
print(O)
